import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Check, Copy } from 'lucide-react';
import { DEFAULT_PROJECT_CONFIG } from '../types';
import type { ProjectConfig } from '../types';
import { generateConfigText, KNOWN_CONFIG_KEYS } from '../utils/configText';

/**
 * The `config.txt` these settings write, exactly as it will land on the card.
 *
 * Generated by the same function the writers use, so what is shown is what is
 * written. Values that differ from the device default are lit, a value that just
 * changed flashes, and pairs kept from the file without a control here are dimmed.
 */

interface Line {
    text: string;
    /** For a value line, the key it belongs to. */
    key?: string;
    isKey?: boolean;
    changedFromDefault?: boolean;
    kept?: boolean;
}

const DEFAULT_VALUES = valuesOf(generateConfigText(DEFAULT_PROJECT_CONFIG));

/** key -> value, walking the non-blank lines as pairs the way the parser does. */
function valuesOf(text: string): Map<string, string> {
    const pairs = text.split('\n').map(l => l.trim()).filter(Boolean);
    const out = new Map<string, string>();
    for (let i = 0; i + 1 < pairs.length; i += 2) out.set(pairs[i], pairs[i + 1]);
    return out;
}

const isKnown = (key: string) => KNOWN_CONFIG_KEYS.some(k => key.toUpperCase().startsWith(k));

/** Every line of the file, blank ones included, each marked as a key or as the value of one. */
function linesOf(text: string): Line[] {
    const out: Line[] = [];
    let pendingKey: string | null = null;
    for (const raw of text.split('\n')) {
        const t = raw.trim();
        if (!t) {
            out.push({ text: raw });
        } else if (pendingKey === null) {
            pendingKey = t;
            out.push({ text: raw, isKey: true, kept: !isKnown(t) });
        } else {
            const known = isKnown(pendingKey);
            out.push({ text: raw, key: pendingKey, kept: !known, changedFromDefault: known && DEFAULT_VALUES.get(pendingKey) !== t });
            pendingKey = null;
        }
    }
    return out;
}

export const ConfigTextPreview: React.FC<{ config: ProjectConfig }> = ({ config }) => {
    const text = useMemo(() => generateConfigText(config), [config]);
    const [copied, setCopied] = useState(false);
    const [flashing, setFlashing] = useState<Set<string>>(new Set());
    const previous = useRef<Map<string, string> | null>(null);

    const lines = useMemo(() => linesOf(text), [text]);

    // Flash the values that changed since the last render. Not on first render:
    // opening the editor is not a change.
    useEffect(() => {
        const now = valuesOf(text);
        const before = previous.current;
        previous.current = now;
        if (!before) return;
        const changed = new Set([...now].filter(([k, v]) => before.get(k) !== v).map(([k]) => k));
        if (changed.size === 0) return;
        setFlashing(changed);
        const t = setTimeout(() => setFlashing(new Set()), 900);
        return () => clearTimeout(t);
    }, [text]);

    useEffect(() => {
        if (!copied) return;
        const t = setTimeout(() => setCopied(false), 1500);
        return () => clearTimeout(t);
    }, [copied]);

    const handleCopy = async () => {
        try {
            await navigator.clipboard.writeText(text);
            setCopied(true);
        } catch (e) {
            console.warn('[Config] Copy failed:', e);
        }
    };

    return (
        <div className="md:sticky md:top-0 rounded-xl border border-gray-800 bg-black/40 overflow-hidden">
            <div className="flex items-center justify-between px-3 py-2 border-b border-gray-800">
                <span className="font-mono text-[10px] text-gray-500">SK/config.txt</span>
                <button
                    onClick={handleCopy}
                    title="Copy the file's text"
                    className="flex items-center gap-1 text-[10px] text-gray-500 hover:text-white transition-colors"
                >
                    {copied ? <Check size={12} className="text-synthux-yellow" /> : <Copy size={12} />}
                    {copied ? 'Copied' : 'Copy'}
                </button>
            </div>
            <pre className="max-h-[50vh] md:max-h-[60vh] overflow-auto custom-scrollbar py-2 font-mono text-[11px] leading-4" aria-label="config.txt contents">
                {lines.map((line, i) => (
                    <div
                        key={i}
                        className={`flex px-2 transition-colors duration-700 ${line.text.trim() ? '' : 'h-2 overflow-hidden'} ${line.key && flashing.has(line.key) ? 'bg-synthux-yellow/25' : ''}`}
                    >
                        {/* Blank separators sit at half height, so they go unnumbered; the count still includes them. */}
                        <span className="w-6 shrink-0 pr-2 text-right text-gray-700 select-none">{line.text.trim() ? i + 1 : ''}</span>
                        <span
                            title={line.kept ? 'Kept from the file: no control for it here' : undefined}
                            className={
                                line.kept ? 'text-gray-600 italic'
                                    : line.isKey ? 'text-gray-400'
                                        : line.changedFromDefault ? 'text-synthux-yellow font-bold'
                                            : 'text-white'
                            }
                        >
                            {line.text || ' '}
                        </span>
                    </div>
                ))}
            </pre>
            <div className="px-3 py-1.5 border-t border-gray-800 text-[9px] text-gray-600 leading-relaxed">
                <span className="text-synthux-yellow">Yellow</span>: differs from the default file.
            </div>
        </div>
    );
};
